	private static RowState runtimeRow(SyntheticValueSource source, Value value) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("a", 0), null);
		layout.freeze(List.of("a"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		row.slots[0] = source.internComputedValue(value);
		row.recomputeBoundMask();
		return row;
	}

	private static LmdbNativeValueCodec.DecodedValue decodedLiteral(String value) {
		return LmdbNativeValueCodec.fromValue(SimpleValueFactory.getInstance().createLiteral(value));
	}

	private static final class TrackingForkFilter implements NativeBooleanFilter {
		private final boolean throwOnFork;
		private final RuntimeException closeFailure;
		private final AtomicInteger forkedCloseCount = new AtomicInteger();

		private TrackingForkFilter(boolean throwOnFork) {
			this(throwOnFork, null);
		}

		private TrackingForkFilter(boolean throwOnFork, RuntimeException closeFailure) {
			this.throwOnFork = throwOnFork;
			this.closeFailure = closeFailure;
		}

		@Override
		public boolean parallelWorkerForkable() {
			return true;
		}

		@Override
		public NativeBooleanFilter forkForParallelWorker() {
			return fork();
		}

		@Override
		public NativeBooleanFilter forkForParallelWorker(NativeScalarPlan.WorkerContext context) {
			return fork();
		}

		private NativeBooleanFilter fork() {
			if (throwOnFork) {
				throw new IllegalStateException("right fork failed");
			}
			return new NativeBooleanFilter() {
				@Override
				public boolean accept(RowState row) {
					return true;
				}

				@Override
				public void close() {
					forkedCloseCount.incrementAndGet();
					if (closeFailure != null) {
						throw closeFailure;
					}
				}
			};
		}

		@Override
		public boolean accept(RowState row) {
			return true;
		}
	}

	private static final class CloseFailingFilter implements NativeBooleanFilter {
		private final RuntimeException failure;
		private int closeCount;

		private CloseFailingFilter(RuntimeException failure) {
			this.failure = failure;
		}

		@Override
		public boolean accept(RowState row) {
			return true;
		}

		@Override
		public void close() {
			closeCount++;
			throw failure;
		}
	}

	@Test
	void semanticBooleanRetainsItsExactSlotReadMask() {
		Compare oneSlot = new Compare(new Var("a"),
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral("")), Compare.CompareOp.NE);
		Compare twoSlots = new Compare(new Var("a"), new Var("b"), Compare.CompareOp.NE);
		Compare outsideFragment = new Compare(new Var("outside"), new Var("a"), Compare.CompareOp.NE);

		assertThat(compiler.compileSemanticBoolean(oneSlot).batchReadMask()).isEqualTo(1L);
		assertThat(compiler.compileSemanticBoolean(twoSlots).batchReadMask()).isEqualTo(3L);
		assertThat(compiler.compileSemanticBoolean(outsideFragment).batchReadMask())
				.as("a name owned by an outer fragment cannot be represented by this fragment's slot mask")
				.isEqualTo(-1L);
	}

